            live_repo_root=ctx.roots.live_repo_root,
        )
        authority = build_repository_authority(
            project_root=ctx.roots.project_root,
            live_repo_root=data_root,
        )
        return preparation_state.build_roster(
            repo_root=data_root,
            authority=authority,
